-- Altsetter: Muskeln, Equipment und Übungen auf Deutsch und Englisch.
--
-- Legt Schema und alle Daten einmalig an (tools/migrate.sh); danach liest die API sie nur noch.
--
-- IDs sind englisch, klein und mit Bindestrichen (z. B. 'upper-chest', 'lat-pulldown') und für alle
-- Sprachen gleich. Dieselben IDs stehen in den Pfaden der App, deshalb sind sie stabil und Teil der
-- API. Die Datenbank lässt nur dieses Format zu (Constraint *_id_format), höchstens 64 Zeichen.
--
-- Sprachneutrales (IDs, lateinische Namen, Reihenfolge, Schwierigkeit) steht in den Haupttabellen,
-- alle Texte in *_text bzw. exercise_tip, je Sprache eine Zeile. Eine weitere Sprache braucht nur
-- einen Eintrag in "language" und ihre Texte.

CREATE TABLE language (
    code  text PRIMARY KEY,
    CONSTRAINT language_code_format CHECK (code ~ '^[a-z]{2}$')
);

INSERT INTO language (code) VALUES ('de'), ('en');

CREATE TABLE muscle_family (
    id          text     PRIMARY KEY,
    latin_name  text     NOT NULL,
    sort_order  smallint NOT NULL,
    CONSTRAINT muscle_family_id_format CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(id) <= 64)
);

CREATE TABLE muscle_family_text (
    family_id  text NOT NULL REFERENCES muscle_family (id) ON DELETE CASCADE,
    language   text NOT NULL REFERENCES language (code),
    name       text NOT NULL,
    region     text NOT NULL,
    summary    text NOT NULL,
    PRIMARY KEY (family_id, language)
);

CREATE TABLE muscle (
    id          text     PRIMARY KEY,
    family_id   text     REFERENCES muscle_family (id),
    latin_name  text     NOT NULL,
    sort_order  smallint NOT NULL,
    CONSTRAINT muscle_id_format CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(id) <= 64)
);

CREATE INDEX muscle_family_id_idx ON muscle (family_id);

CREATE TABLE muscle_text (
    muscle_id  text NOT NULL REFERENCES muscle (id) ON DELETE CASCADE,
    language   text NOT NULL REFERENCES language (code),
    name       text NOT NULL,
    region     text NOT NULL,
    summary    text NOT NULL,
    PRIMARY KEY (muscle_id, language)
);

-- Mesh-Namen im 3D-Modell ohne Seite, z. B. 'Long head of biceps brachii'.
CREATE TABLE muscle_mesh (
    muscle_id  text NOT NULL REFERENCES muscle (id) ON DELETE CASCADE,
    mesh_name  text NOT NULL,
    PRIMARY KEY (muscle_id, mesh_name)
);

CREATE TABLE equipment (
    id          text     PRIMARY KEY,
    sort_order  smallint NOT NULL,
    CONSTRAINT equipment_id_format CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(id) <= 64)
);

CREATE TABLE equipment_text (
    equipment_id  text NOT NULL REFERENCES equipment (id) ON DELETE CASCADE,
    language      text NOT NULL REFERENCES language (code),
    name          text NOT NULL,
    PRIMARY KEY (equipment_id, language),
    UNIQUE (language, name)
);

CREATE TABLE exercise (
    id          text PRIMARY KEY,
    difficulty  text NOT NULL CHECK (difficulty IN ('beginner', 'intermediate', 'advanced')),
    CONSTRAINT exercise_id_format CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(id) <= 64)
);

CREATE TABLE exercise_text (
    exercise_id  text NOT NULL REFERENCES exercise (id) ON DELETE CASCADE,
    language     text NOT NULL REFERENCES language (code),
    name         text NOT NULL,
    description  text NOT NULL,
    PRIMARY KEY (exercise_id, language)
);

-- Für die Liste: Übungen einer Sprache nach Name sortiert.
CREATE INDEX exercise_text_language_name_idx ON exercise_text (language, name);

CREATE TABLE exercise_equipment (
    exercise_id   text NOT NULL REFERENCES exercise (id) ON DELETE CASCADE,
    equipment_id  text NOT NULL REFERENCES equipment (id),
    PRIMARY KEY (exercise_id, equipment_id)
);

CREATE INDEX exercise_equipment_equipment_idx ON exercise_equipment (equipment_id);

-- primary: Hauptmuskeln der Übung, secondary: Muskeln, die mitarbeiten.
CREATE TABLE exercise_muscle (
    exercise_id  text NOT NULL REFERENCES exercise (id) ON DELETE CASCADE,
    muscle_id    text NOT NULL REFERENCES muscle (id),
    role         text NOT NULL CHECK (role IN ('primary', 'secondary')),
    PRIMARY KEY (exercise_id, muscle_id)
);

-- Für die häufigste Abfrage: alle Übungen eines Muskels.
CREATE INDEX exercise_muscle_muscle_idx ON exercise_muscle (muscle_id, role);

-- cue: „Darauf achten“, mistake: „Häufige Fehler“; je Sprache eigene Zeilen.
CREATE TABLE exercise_tip (
    exercise_id  text     NOT NULL REFERENCES exercise (id) ON DELETE CASCADE,
    language     text     NOT NULL REFERENCES language (code),
    kind         text     NOT NULL CHECK (kind IN ('cue', 'mistake')),
    position     smallint NOT NULL,
    text         text     NOT NULL,
    PRIMARY KEY (exercise_id, language, kind, position)
);

-- ---------------------------------------------------------------------------------------------
-- Muskelgruppen, Muskeln und ihre Meshes im 3D-Modell der App. Reihenfolge: von oben nach unten.

