INSERT INTO muscle_family_text (family_id, language, name, region, summary) VALUES
  ('chest', 'de', 'Brust', 'Brust', 'Der Hauptmuskel der Brust mit oberem, mittlerem und unterem Anteil. Zieht den Oberarm vor den Körper – je nach Winkel der Übung wird ein anderer Teil stärker gefordert.'),
  ('chest', 'en', 'Chest', 'Chest', 'The main chest muscle, with an upper, middle and lower part. Pulls the upper arm across the front of the body – depending on the angle of the exercise, a different part works harder.'),
  ('shoulders', 'de', 'Schulter', 'Schultern', 'Die Schulterkappe aus vorderem, seitlichem und hinterem Anteil. Hebt den Arm in alle Richtungen. Für runde, breite Schultern braucht jeder Teil eigene Übungen.'),
  ('shoulders', 'en', 'Shoulders', 'Shoulders', 'The shoulder cap, made of a front, side and rear part. Raises the arm in every direction. For round, broad shoulders, each part needs its own exercises.'),
  ('traps', 'de', 'Trapez', 'Rücken', 'Großer, rautenförmiger Muskel im oberen Rücken mit oberem, mittlerem und unterem Anteil. Bewegt und stabilisiert die Schulterblätter.'),
  ('traps', 'en', 'Traps', 'Back', 'A large, diamond-shaped muscle in the upper back with an upper, middle and lower part. Moves and stabilises the shoulder blades.'),
  ('biceps', 'de', 'Bizeps', 'Arme', 'Die Armbeuger auf der Vorderseite des Oberarms: der zweiköpfige Bizeps und der darunterliegende Oberarmmuskel (Brachialis). Beugen den Ellbogen; der Bizeps dreht zusätzlich die Handfläche nach oben.'),
  ('biceps', 'en', 'Biceps', 'Arms', 'The elbow flexors on the front of the upper arm: the two-headed biceps and the brachialis underneath it. They bend the elbow; the biceps also turns the palm up.'),
  ('triceps', 'de', 'Trizeps', 'Arme', 'Der dreiköpfige Streckmuskel auf der Rückseite des Oberarms – macht etwa zwei Drittel des Oberarmumfangs aus. Streckt den Ellbogen; der lange Kopf zieht zusätzlich den Arm nach hinten.'),
  ('triceps', 'en', 'Triceps', 'Arms', 'The three-headed extensor on the back of the upper arm – it makes up about two thirds of the arm''s size. Straightens the elbow; the long head also pulls the arm back.'),
  ('quads', 'de', 'Quadrizeps', 'Beine', 'Die Vorderseite des Oberschenkels. Streckt das Knie und ist bei Kniebeugen, Beinpresse und beim Treppensteigen der Hauptmuskel.'),
  ('quads', 'en', 'Quads', 'Legs', 'The front of the thigh. Straightens the knee and is the main muscle in squats, the leg press and climbing stairs.'),
  ('lower-legs', 'de', 'Unterschenkel', 'Beine', 'Alle Muskeln zwischen Knie und Fuß: die Wade (Gastrocnemius und Soleus) hinten, der Schienbeinmuskel vorn und die Peroneus-Muskeln außen. Sie bewegen und stabilisieren das Sprunggelenk.'),
  ('lower-legs', 'en', 'Lower Legs', 'Legs', 'All the muscles between knee and foot: the calf (gastrocnemius and soleus) at the back, the tibialis at the front and the peroneals on the outside. They move and stabilise the ankle.'),
  ('glutes', 'de', 'Gesäß', 'Hüfte', 'Der Po aus drei Muskeln: der große Gesäßmuskel streckt die Hüfte, der mittlere und der kleine darunter spreizen das Bein ab und halten das Becken stabil. Für ein rundes Gesäß braucht jeder eigene Übungen.'),
  ('glutes', 'en', 'Glutes', 'Hips', 'The backside, made of three muscles: the gluteus maximus extends the hip, while the medius and minimus underneath move the leg out to the side and keep the pelvis stable. For round glutes, each needs its own exercises.'),
  ('forearms', 'de', 'Unterarm', 'Arme', 'Die Muskeln zwischen Ellbogen und Hand: die Beuger auf der Handflächenseite, die Strecker auf der Rückseite und der kräftige Brachioradialis auf der Daumenseite. Entscheidend für Griffkraft und gesunde Ellbogen.'),
  ('forearms', 'en', 'Forearms', 'Arms', 'The muscles between elbow and hand: the flexors on the palm side, the extensors on the back and the strong brachioradialis on the thumb side. Key to grip strength and healthy elbows.');

