INSERT INTO muscle_text (muscle_id, language, name, region, summary) VALUES
  ('upper-chest', 'de', 'Obere Brust', 'Brust', 'Der obere Anteil des Brustmuskels, der am Schlüsselbein entspringt. Hebt den Arm schräg nach vorn oben und formt den Übergang von Brust zu Schulter.'),
  ('upper-chest', 'en', 'Upper Chest', 'Chest', 'The upper part of the chest muscle, which starts at the collarbone. Raises the arm forward and up at an angle and shapes the transition from chest to shoulder.'),
  ('mid-chest', 'de', 'Mittlere Brust', 'Brust', 'Der größte Anteil des Brustmuskels, entspringt am Brustbein. Zieht den Arm waagerecht vor den Körper und gibt der Brust ihre Fülle.'),
  ('mid-chest', 'en', 'Mid Chest', 'Chest', 'The largest part of the chest muscle, starting at the breastbone. Pulls the arm horizontally across the body and gives the chest its fullness.'),
  ('lower-chest', 'de', 'Untere Brust', 'Brust', 'Der untere Rand des Brustmuskels, entspringt an der Bauchmuskelscheide. Zieht den Arm von oben nach unten vor den Körper und formt die untere Brustlinie.'),
  ('lower-chest', 'en', 'Lower Chest', 'Chest', 'The lower edge of the chest muscle, starting at the sheath of the abdominal muscles. Pulls the arm down and across the body and shapes the lower chest line.'),
  ('serratus', 'de', 'Sägezahnmuskel', 'Brust', 'Der „Boxermuskel“ seitlich an den Rippen. Zieht das Schulterblatt nach vorn und oben.'),
  ('serratus', 'en', 'Serratus', 'Chest', 'The "boxer''s muscle" on the side of the ribs. Pulls the shoulder blade forward and up.'),
  ('front-delts', 'de', 'Vordere Schulter', 'Schultern', 'Der vordere Anteil des Deltamuskels. Hebt den Arm nach vorn und arbeitet bei allen Druckübungen mit – wird durch Bankdrücken oft schon gut trainiert.'),
  ('front-delts', 'en', 'Front Delts', 'Shoulders', 'The front part of the deltoid. Raises the arm forward and helps in every pressing exercise – often already well trained by bench pressing.'),
  ('side-delts', 'de', 'Seitliche Schulter', 'Schultern', 'Der mittlere Anteil des Deltamuskels. Hebt den Arm zur Seite und ist für die Schulterbreite verantwortlich.'),
  ('side-delts', 'en', 'Side Delts', 'Shoulders', 'The middle part of the deltoid. Raises the arm to the side and is responsible for shoulder width.'),
  ('rear-delts', 'de', 'Hintere Schulter', 'Schultern', 'Der hintere Anteil des Deltamuskels. Zieht den Arm nach hinten, sorgt für eine runde Schulter von der Seite und eine gesunde Haltung.'),
  ('rear-delts', 'en', 'Rear Delts', 'Shoulders', 'The rear part of the deltoid. Pulls the arm back, rounds out the shoulder from the side and supports healthy posture.'),
  ('rotator-cuff', 'de', 'Rotatorenmanschette', 'Schultern', 'Kleine Muskeln auf dem Schulterblatt. Drehen den Arm nach außen und stabilisieren das Schultergelenk.'),
  ('rotator-cuff', 'en', 'Rotator Cuff', 'Shoulders', 'Small muscles on the shoulder blade. They rotate the arm outward and stabilise the shoulder joint.'),
  ('upper-traps', 'de', 'Oberer Trapez', 'Rücken', 'Der obere Anteil zwischen Nacken und Schulter. Zieht die Schultern nach oben und formt den Nacken.'),
  ('upper-traps', 'en', 'Upper Traps', 'Back', 'The upper part between neck and shoulder. Pulls the shoulders up and shapes the neck.'),
  ('middle-traps', 'de', 'Mittlerer Trapez', 'Rücken', 'Der mittlere Anteil zwischen den Schulterblättern. Zieht die Schulterblätter zusammen und sorgt für einen dichten oberen Rücken.'),
  ('middle-traps', 'en', 'Middle Traps', 'Back', 'The middle part between the shoulder blades. Pulls the shoulder blades together and gives the upper back its thickness.'),
  ('lower-traps', 'de', 'Unterer Trapez', 'Rücken', 'Der untere Anteil, der bis zur Brustwirbelsäule reicht. Zieht die Schulterblätter nach unten – wichtig für Haltung und Überkopfbewegungen.'),
  ('lower-traps', 'en', 'Lower Traps', 'Back', 'The lower part, which reaches down to the thoracic spine. Pulls the shoulder blades down – important for posture and overhead movements.'),
  ('lats', 'de', 'Latissimus', 'Rücken', 'Der große Rückenmuskel, der die Arme nach unten und hinten zieht. Sorgt für das V-Kreuz.'),
  ('lats', 'en', 'Lats', 'Back', 'The large back muscle that pulls the arms down and back. Creates the V-taper.'),
  ('lower-back', 'de', 'Unterer Rücken', 'Rücken', 'Die langen Muskelstränge entlang der Wirbelsäule. Halten den Rücken gerade und strecken den Rumpf.'),
  ('lower-back', 'en', 'Lower Back', 'Back', 'The long muscle strands along the spine. They keep the back straight and extend the torso.'),
  ('neck', 'de', 'Nacken', 'Nacken', 'Muskeln an Hals und Nacken, die den Kopf bewegen und stabilisieren.'),
  ('neck', 'en', 'Neck', 'Neck', 'Muscles of the neck that move and stabilise the head.'),
  ('biceps-long-head', 'de', 'Langer Bizeps', 'Arme', 'Der äußere Kopf des Bizeps, seine Sehne läuft über das Schultergelenk. Formt den Bizeps-„Peak“ und wird am stärksten gedehnt, wenn der Arm hinter dem Körper ist.'),
  ('biceps-long-head', 'en', 'Biceps Long Head', 'Arms', 'The outer head of the biceps; its tendon runs over the shoulder joint. Shapes the biceps peak and is stretched most when the arm is behind the body.'),
  ('biceps-short-head', 'de', 'Kurzer Bizeps', 'Arme', 'Der innere Kopf des Bizeps, entspringt am Rabenschnabelfortsatz. Gibt dem Bizeps Breite und arbeitet am stärksten, wenn der Arm vor dem Körper ist.'),
  ('biceps-short-head', 'en', 'Biceps Short Head', 'Arms', 'The inner head of the biceps, starting at the coracoid process. Gives the biceps width and works hardest when the arm is in front of the body.'),
  ('brachialis', 'de', 'Brachialis', 'Arme', 'Liegt unter dem Bizeps und ist der stärkste reine Ellbogenbeuger. Drückt den Bizeps nach oben und macht den Arm dicker.'),
  ('brachialis', 'en', 'Brachialis', 'Arms', 'Lies under the biceps and is the strongest pure elbow flexor. Pushes the biceps up and makes the arm thicker.'),
  ('brachioradialis', 'de', 'Brachioradialis', 'Arme', 'Der kräftige Unterarmmuskel auf der Daumenseite. Beugt den Ellbogen im neutralen Griff.'),
  ('brachioradialis', 'en', 'Brachioradialis', 'Arms', 'The strong forearm muscle on the thumb side. Bends the elbow with a neutral grip.'),
  ('triceps-long-head', 'de', 'Langer Trizeps', 'Arme', 'Der größte Kopf des Trizeps, auf der Innen- und Rückseite des Oberarms. Setzt am Schulterblatt an und wird deshalb vor allem bei Übungen über Kopf gedehnt und gefordert.'),
  ('triceps-long-head', 'en', 'Triceps Long Head', 'Arms', 'The largest head of the triceps, on the inner and back side of the upper arm. It attaches to the shoulder blade, so it is stretched and worked mainly in overhead exercises.'),
  ('triceps-lateral-head', 'de', 'Seitlicher Trizeps', 'Arme', 'Der äußere Kopf des Trizeps, gut sichtbar als „Hufeisen“ an der Außenseite des Oberarms. Arbeitet besonders bei schweren Druckübungen mit.'),
  ('triceps-lateral-head', 'en', 'Triceps Lateral Head', 'Arms', 'The outer head of the triceps, clearly visible as the "horseshoe" on the outside of the upper arm. Works especially hard in heavy pressing exercises.'),
  ('triceps-medial-head', 'de', 'Mittlerer Trizeps', 'Arme', 'Liegt tief unter den anderen beiden Köpfen, mit dem kleinen Anconeus am Ellbogen. Arbeitet bei jeder Ellbogenstreckung mit, besonders im Untergriff und bei leichter Last.'),
  ('triceps-medial-head', 'en', 'Triceps Medial Head', 'Arms', 'Lies deep under the other two heads, together with the small anconeus at the elbow. Works in every elbow extension, especially with an underhand grip and light loads.'),
  ('forearm-flexors', 'de', 'Unterarmbeuger (innen)', 'Arme', 'Muskeln auf der Handflächenseite des Unterarms. Beugen Handgelenk und Finger – entscheidend für die Griffkraft.'),
  ('forearm-flexors', 'en', 'Forearm Flexors', 'Arms', 'Muscles on the palm side of the forearm. They bend the wrist and fingers – key to grip strength.'),
  ('forearm-extensors', 'de', 'Unterarmstrecker (außen)', 'Arme', 'Muskeln auf der Rückseite des Unterarms. Heben Handgelenk und Finger und gleichen das Grifftraining aus.'),
  ('forearm-extensors', 'en', 'Forearm Extensors', 'Arms', 'Muscles on the back of the forearm. They raise the wrist and fingers and balance out grip training.'),
  ('abs', 'de', 'Bauch', 'Rumpf', 'Das „Sixpack“. Beugt die Wirbelsäule und stabilisiert den Rumpf.'),
  ('abs', 'en', 'Abs', 'Core', 'The "six-pack". Bends the spine and stabilises the core.'),
  ('obliques', 'de', 'Schräge Bauchmuskeln', 'Rumpf', 'Die seitlichen und tiefen Bauchmuskeln. Drehen und neigen den Rumpf und spannen den Bauch wie ein Korsett.'),
  ('obliques', 'en', 'Obliques', 'Core', 'The side and deep abdominal muscles. They rotate and bend the torso and brace the stomach like a corset.'),
  ('gluteus-maximus', 'de', 'Großer Gesäßmuskel', 'Hüfte', 'Der größte Muskel des Körpers und der sichtbare, runde Teil des Pos. Streckt die Hüfte – der Motor beim Sprinten, Springen und Heben.'),
  ('gluteus-maximus', 'en', 'Gluteus Maximus', 'Hips', 'The largest muscle in the body and the visible, round part of the backside. Extends the hip – the engine for sprinting, jumping and lifting.'),
  ('gluteus-medius', 'de', 'Mittlerer Gesäßmuskel', 'Hüfte', 'Sitzt seitlich oben an der Hüfte, mit dem Faszienzug (Tractus iliotibialis) an der Oberschenkelaußenseite. Spreizt das Bein ab und hält das Becken gerade, wenn man auf einem Bein steht. Formt die obere, seitliche Rundung des Pos.'),
  ('gluteus-medius', 'en', 'Gluteus Medius', 'Hips', 'Sits high on the side of the hip, with the iliotibial band on the outside of the thigh. Moves the leg out to the side and keeps the pelvis level when standing on one leg. Shapes the upper, outer curve of the glutes.'),
  ('gluteus-minimus', 'de', 'Kleiner Gesäßmuskel', 'Hüfte', 'Der tiefste der drei Gesäßmuskeln, unter dem mittleren. Hilft beim Abspreizen, dreht das Bein nach innen und stabilisiert das Hüftgelenk bei jedem Schritt.'),
  ('gluteus-minimus', 'en', 'Gluteus Minimus', 'Hips', 'The deepest of the three glute muscles, under the medius. Helps move the leg out to the side, rotates it inward and stabilises the hip joint with every step.'),
  ('hip-flexors', 'de', 'Hüftbeuger', 'Hüfte', 'Ziehen das Knie Richtung Brust. Bestehen aus Darmbeinmuskel, großem Lendenmuskel und Schneidermuskel.'),
  ('hip-flexors', 'en', 'Hip Flexors', 'Hips', 'Pull the knee toward the chest. Made up of the iliacus, the psoas major and the sartorius.'),
  ('adductors', 'de', 'Adduktoren', 'Hüfte', 'Die Innenseite des Oberschenkels. Ziehen die Beine zusammen und helfen bei Kniebeugen.'),
  ('adductors', 'en', 'Adductors', 'Hips', 'The inside of the thigh. They pull the legs together and help in squats.'),
  ('rectus-femoris', 'de', 'Rectus femoris', 'Beine', 'Der mittlere, oberflächliche Teil des Quadrizeps. Als einziger Teil zieht er über Knie und Hüfte – er streckt das Knie und beugt die Hüfte. Bei Kniebeugen arbeitet er deshalb eher wenig.'),
  ('rectus-femoris', 'en', 'Rectus Femoris', 'Legs', 'The middle, surface part of the quads. It is the only part that crosses both knee and hip – it straightens the knee and flexes the hip. That''s why it works relatively little in squats.'),
  ('vastus-lateralis', 'de', 'Äußerer Quadrizeps', 'Beine', 'Der größte Teil des Quadrizeps an der Außenseite des Oberschenkels. Gibt dem Bein seine Breite. Er arbeitet bei allen Kniebeugen und Pressen stark mit.'),
  ('vastus-lateralis', 'en', 'Vastus Lateralis', 'Legs', 'The largest part of the quads, on the outside of the thigh. Gives the leg its width and works hard in all squats and presses.'),
  ('vastus-medialis', 'de', 'Innerer Quadrizeps (Träne)', 'Beine', 'Die „Träne“ an der Innenseite über dem Knie. Stabilisiert die Kniescheibe. Lässt sich nur begrenzt isolieren, profitiert aber von tiefen Kniebeugen mit weit nach vorn geschobenen Knien.'),
  ('vastus-medialis', 'en', 'Vastus Medialis (Teardrop)', 'Legs', 'The "teardrop" on the inside just above the knee. Stabilises the kneecap. Can only be isolated to a limited extent, but benefits from deep squats with the knees pushed far forward.'),
  ('hamstrings', 'de', 'Beinbeuger', 'Beine', 'Die Rückseite des Oberschenkels. Beugt das Knie und streckt die Hüfte.'),
  ('hamstrings', 'en', 'Hamstrings', 'Legs', 'The back of the thigh. Bends the knee and extends the hip.'),
  ('gastrocnemius', 'de', 'Wade (Gastrocnemius)', 'Beine', 'Der sichtbare, zweiköpfige Teil der Wade, der über die Achillessehne an der Ferse ansetzt. Zieht auch über das Knie und arbeitet deshalb am stärksten bei gestreckten Beinen.'),
  ('gastrocnemius', 'en', 'Calves (Gastrocnemius)', 'Legs', 'The visible, two-headed part of the calf, which attaches to the heel via the Achilles tendon. It also crosses the knee, so it works hardest with straight legs.'),
  ('soleus', 'de', 'Wade (Soleus)', 'Beine', 'Liegt flach unter dem Zwillingswadenmuskel, zusammen mit den tiefen Wadenmuskeln. Zieht nur über das Sprunggelenk und arbeitet deshalb vor allem bei gebeugten Knien.'),
  ('soleus', 'en', 'Calves (Soleus)', 'Legs', 'Lies flat under the gastrocnemius, together with the deep calf muscles. Only crosses the ankle, so it works mainly with bent knees.'),
  ('tibialis', 'de', 'Schienbein', 'Beine', 'Die Muskeln vorn am Schienbein. Ziehen Fuß und Zehen nach oben.'),
  ('tibialis', 'en', 'Tibialis', 'Legs', 'The muscles at the front of the shin. They pull the foot and toes up.'),
  ('peroneals', 'de', 'Peroneus', 'Beine', 'An der Außenseite des Unterschenkels. Drehen die Fußsohle nach außen und stabilisieren das Sprunggelenk.'),
  ('peroneals', 'en', 'Peroneals', 'Legs', 'On the outside of the lower leg. They turn the sole of the foot outward and stabilise the ankle.');

