INSERT INTO exercise_text (exercise_id, language, name, description) VALUES
  ('ab-crunch-machine', 'de', 'Bauchmaschine', 'An der Bauchmaschine den Oberkörper gegen das Gewicht einrollen. Lässt sich leicht steigern und eignet sich für schwerere Bauchübungen.'),
  ('ab-crunch-machine', 'en', 'Ab Crunch Machine', 'Curl your upper body against the weight on the ab machine. Easy to progress and good for heavier ab work.'),
  ('ab-wheel-rollout', 'de', 'Bauchroller', 'Aus den Knien nach vorn rollen, ohne ins Hohlkreuz zu fallen, und wieder zurückziehen. Fordert den Bauch stark, weil er die Streckung bremsen muss.'),
  ('ab-wheel-rollout', 'en', 'Ab Wheel Rollout', 'Roll forward from your knees without sagging into an arched back, then pull back. Very demanding on the abs because they have to brake the extension.'),
  ('alternating-dumbbell-curls', 'de', 'Kurzhantel-Curls im Wechsel', 'Abwechselnd mit jedem Arm curlen und dabei die Handfläche nach oben drehen. Jeder Arm arbeitet für sich, Seitenunterschiede fallen auf.'),
  ('alternating-dumbbell-curls', 'en', 'Alternating Dumbbell Curls', 'Curl with each arm in turn, rotating your palm up as you go. Each arm works on its own, so side imbalances show.'),
  ('arnold-press', 'de', 'Arnold Press', 'Mit den Handflächen zum Körper starten und beim Hochdrücken nach außen drehen. Langer Bewegungsweg mit Schwerpunkt auf der vorderen Schulter.'),
  ('arnold-press', 'en', 'Arnold Press', 'Start with your palms facing you and rotate them outward as you press up. Long range of motion with the focus on the front delts.'),
  ('assisted-pull-ups', 'de', 'Klimmzüge an der Unterstützungsmaschine', 'Klimmzüge mit Unterstützung: Ein Gegengewicht nimmt einen Teil des Körpergewichts ab. Der Einstieg zu freien Klimmzügen.'),
  ('assisted-pull-ups', 'en', 'Assisted Pull-Ups', 'Pull-ups with assistance: a counterweight takes off part of your body weight. The way into unassisted pull-ups.'),
  ('back-extensions', 'de', 'Hyperextensions', 'Über das Polster nach vorn beugen und den Oberkörper wieder in eine gerade Linie heben. Mit einer Hantelscheibe vor der Brust leicht zu steigern.'),
  ('back-extensions', 'en', 'Back Extensions', 'Bend forward over the pad and raise your upper body back into a straight line. Easy to progress with a weight plate held at your chest.'),
  ('banded-lateral-walks', 'de', 'Seitwärtsgehen mit Miniband', 'Band um Knie oder Knöchel, in leichter Kniebeuge seitwärts gehen. Ideal zum Aufwärmen vor Kniebeugen.'),
  ('banded-lateral-walks', 'en', 'Banded Lateral Walks', 'Band around your knees or ankles, walk sideways in a slight squat. Ideal as a warm-up before squats.'),
  ('barbell-back-squats', 'de', 'Kniebeugen mit der Langhantel', 'Mit der Stange auf dem oberen Rücken mindestens bis zur Parallelen beugen. Die Grundübung für Kraft im Unterkörper.'),
  ('barbell-back-squats', 'en', 'Barbell Back Squats', 'With the bar on your upper back, squat at least to parallel. The foundational exercise for lower-body strength.'),
  ('barbell-bench-press', 'de', 'Bankdrücken mit der Langhantel', 'Schulterblätter zusammenziehen, die Stange kontrolliert zur mittleren Brust absenken und wieder hochdrücken. Der Klassiker für eine kräftige Brust.'),
  ('barbell-bench-press', 'en', 'Barbell Bench Press', 'Pull your shoulder blades together, lower the bar under control to your mid chest and press it back up. The classic for a strong chest.'),
  ('barbell-curls', 'de', 'Langhantel-Curls', 'Der Klassiker für den Bizeps: mit schulterbreitem Untergriff die Stange hochcurlen. Erlaubt das meiste Gewicht aller Curl-Varianten.'),
  ('barbell-curls', 'en', 'Barbell Curls', 'The biceps classic: curl the bar up with a shoulder-width underhand grip. Allows the most weight of all curl variations.'),
  ('barbell-hip-thrusts', 'de', 'Hip Thrusts mit der Langhantel', 'Oberer Rücken auf der Bank, die Stange mit der Hüfte nach oben drücken, bis der Oberkörper waagerecht ist. Maximale Gesäßspannung am höchsten Punkt.'),
  ('barbell-hip-thrusts', 'en', 'Barbell Hip Thrusts', 'Upper back on the bench, drive the bar up with your hips until your torso is horizontal. Maximum glute tension at the top.'),
  ('barbell-rows', 'de', 'Langhantelrudern', 'Vorgebeugt die Langhantel zum Bauch ziehen. Eine der wichtigsten Grundübungen für einen breiten und dichten Rücken.'),
  ('barbell-rows', 'en', 'Barbell Rows', 'Bent over, pull the barbell to your stomach. One of the most important compound exercises for a wide, thick back.'),
  ('barbell-shrugs', 'de', 'Shrugs mit der Langhantel', 'Wie mit Kurzhanteln, aber mit mehr Gewicht möglich. Die Stange vor dem Körper halten und gerade nach oben ziehen.'),
  ('barbell-shrugs', 'en', 'Barbell Shrugs', 'Like with dumbbells, but more weight is possible. Hold the bar in front of your body and pull straight up.'),
  ('bayesian-cable-curls', 'de', 'Bayesian Curls am Kabelzug', 'Mit dem Rücken zum Kabelzug und dem Arm hinter dem Körper curlen. Der Bizeps ist dabei stark gedehnt – besonders gut für den langen Kopf.'),
  ('bayesian-cable-curls', 'en', 'Bayesian Cable Curls', 'Curl with your back to the cable and your arm behind your body. The biceps is strongly stretched – especially good for the long head.'),
  ('bench-dips', 'de', 'Bank-Dips', 'Hände hinter dem Körper auf der Bank, Beine vorn, und den Körper durch Beugen der Arme absenken. Einfache Trizepsübung ohne Geräte.'),
  ('bench-dips', 'en', 'Bench Dips', 'Hands behind you on the bench, legs in front, lower your body by bending your arms. A simple triceps exercise without equipment.'),
  ('bent-over-lateral-raises', 'de', 'Vorgebeugtes Seitheben', 'Mit fast waagerechtem Oberkörper die Kurzhanteln seitlich nach oben führen, Schulterblätter dabei nicht zusammenziehen.'),
  ('bent-over-lateral-raises', 'en', 'Bent-Over Lateral Raises', 'With your upper body almost horizontal, raise the dumbbells out to the sides without squeezing your shoulder blades together.'),
  ('bulgarian-split-squats', 'de', 'Bulgarische Kniebeugen', 'Hinterer Fuß auf der Bank, auf dem vorderen Bein tief nach unten gehen. Schon mit wenig Gewicht sehr fordernd.'),
  ('bulgarian-split-squats', 'en', 'Bulgarian Split Squats', 'Back foot on the bench, go down deep on your front leg. Very demanding even with little weight.'),
  ('cable-biceps-curls', 'de', 'Bizeps-Curls am Kabelzug', 'Die gerade Stange am unteren Kabelzug zur Brust curlen. Der Kabelzug hält den Bizeps auch in der unteren Position unter Spannung.'),
  ('cable-biceps-curls', 'en', 'Cable Biceps Curls', 'Curl the straight bar on the low pulley up to your chest. The cable keeps tension on the biceps even at the bottom.'),
  ('cable-external-rotation', 'de', 'Außenrotation am Kabelzug', 'Ellbogen am Körper und 90° gebeugt, den Griff vom Bauch weg nach außen drehen. Leicht und langsam – hier geht es um Kontrolle, nicht um Gewicht.'),
  ('cable-external-rotation', 'en', 'Cable External Rotation', 'With your elbow at your side and bent 90°, rotate the handle outward away from your stomach. Light and slow – this is about control, not weight.'),
  ('cable-glute-kickbacks', 'de', 'Glute Kickbacks am Kabelzug', 'Ein Bein nach hinten oben strecken, ohne den unteren Rücken zu bewegen. Eine einfache Isolationsübung zum Abschluss.'),
  ('cable-glute-kickbacks', 'en', 'Cable Glute Kickbacks', 'Extend one leg back and up without moving your lower back. A simple isolation exercise to finish with.'),
  ('cable-hip-adduction', 'de', 'Adduktion am Kabelzug', 'Seitlich zum Kabel stehen und das innere Bein vor dem Standbein vorbei nach innen ziehen.'),
  ('cable-hip-adduction', 'en', 'Cable Hip Adduction', 'Stand side-on to the cable and pull the inner leg inward, past the front of your standing leg.'),
  ('cable-lateral-raises', 'de', 'Seitheben am Kabelzug', 'Einarmig vom unteren Kabelzug, der Griff kommt von der gegenüberliegenden Seite. Spannung schon ganz unten, wo Kurzhanteln fast nichts wiegen.'),
  ('cable-lateral-raises', 'en', 'Cable Lateral Raises', 'One arm from the low pulley, with the handle coming from the opposite side. Tension right at the bottom, where dumbbells weigh almost nothing.'),
  ('cable-pull-through', 'de', 'Cable Pull-Through', 'Mit dem Rücken zum Kabelzug das Seil zwischen den Beinen hindurch nach vorne bringen, indem du die Hüfte streckst. Lehrt die Hüftbewegung des Kreuzhebens bei wenig Belastung für den Rücken.'),
  ('cable-pull-through', 'en', 'Cable Pull-Through', 'With your back to the cable, bring the rope forward between your legs by extending your hips. Teaches the hip hinge of the deadlift with little load on the back.'),
  ('cable-shrugs', 'de', 'Shrugs am Kabelzug', 'Shrugs mit einer Stange am unteren Kabelzug. Das Kabel hält die Spannung auch unten, wo Hanteln fast nichts wiegen.'),
  ('cable-shrugs', 'en', 'Cable Shrugs', 'Shrugs with a bar on the low pulley. The cable keeps the tension even at the bottom, where dumbbells weigh almost nothing.'),
  ('cable-straight-arm-pulldown', 'de', 'Überzüge am Kabelzug', 'Mit fast gestreckten Armen den Griff von Augenhöhe bis zu den Oberschenkeln führen. Isoliert den Latissimus, ohne dass der Bizeps übernimmt.'),
  ('cable-straight-arm-pulldown', 'en', 'Cable Straight-Arm Pulldown', 'With almost straight arms, bring the handle from eye level down to your thighs. Isolates the lats without the biceps taking over.'),
  ('cable-woodchoppers', 'de', 'Holzhacker am Kabelzug', 'Den Griff diagonal von oben nach unten quer über den Körper ziehen und dabei aus dem angespannten Rumpf drehen.'),
  ('cable-woodchoppers', 'en', 'Cable Woodchoppers', 'Pull the handle diagonally from high to low across your body, rotating from a braced core.'),
  ('chest-dips', 'de', 'Dips für die Brust', 'Oberkörper nach vorn lehnen und die Ellbogen leicht nach außen nehmen. Trifft die untere Brust mit einer starken Dehnung am tiefsten Punkt.'),
  ('chest-dips', 'en', 'Chest Dips', 'Lean your upper body forward and let your elbows flare slightly. Hits the lower chest with a strong stretch at the bottom.'),
  ('chest-height-cable-flys', 'de', 'Cable Flys auf Brusthöhe', 'Die Kabelzüge auf Schulterhöhe einstellen und die Griffe waagerecht vor der Brust zusammenführen. Gleichmäßige Spannung über den ganzen Weg.'),
  ('chest-height-cable-flys', 'en', 'Chest-Height Cable Flys', 'Set the cables at shoulder height and bring the handles together horizontally in front of your chest. Even tension over the whole range.'),
  ('chest-press-machine', 'de', 'Brustpresse', 'Die Griffe auf Brusthöhe nach vorn drücken. Die geführte Bahn erlaubt es, sicher bis an die Grenze zu trainieren – ganz ohne Spotter.'),
  ('chest-press-machine', 'en', 'Chest Press Machine', 'Press the handles forward at chest height. The guided path lets you train safely to your limit – no spotter needed.'),
  ('chest-supported-row', 'de', 'Brustgestütztes Rudern', 'Bäuchlings auf der Schrägbank mit weit abgespreizten Ellbogen rudern. Das Zusammenziehen der Schulterblätter trifft den mittleren Trapez.'),
  ('chest-supported-row', 'en', 'Chest-Supported Row', 'Row face down on an incline bench with your elbows flared wide. Squeezing the shoulder blades together hits the middle traps.'),
  ('chin-ups', 'de', 'Klimmzüge im Untergriff', 'Klimmzug mit schulterbreitem Untergriff. Eine Grundübung, die den Bizeps zusammen mit dem Latissimus stark fordert.'),
  ('chin-ups', 'en', 'Chin-Ups', 'Pull-up with a shoulder-width underhand grip. A compound exercise that heavily works the biceps together with the lats.'),
  ('close-grip-barbell-curls', 'de', 'Langhantel-Curls mit engem Griff', 'Curls mit Händen enger als schulterbreit. Der enge Griff verlagert die Arbeit etwas mehr auf den langen Kopf.'),
  ('close-grip-barbell-curls', 'en', 'Close-Grip Barbell Curls', 'Curls with your hands narrower than shoulder width. The close grip shifts the work slightly more onto the long head.'),
  ('close-grip-bench-press', 'de', 'Enges Bankdrücken', 'Bankdrücken mit Händen knapp innerhalb der Schulterbreite und Ellbogen am Körper. Schwere Grundübung für den Trizeps.'),
  ('close-grip-bench-press', 'en', 'Close-Grip Bench Press', 'Bench press with your hands just inside shoulder width and elbows close to your body. A heavy compound exercise for the triceps.'),
  ('close-grip-cable-row', 'de', 'Kabelrudern mit engem Griff', 'Im Sitzen den engen Griff zum Bauch ziehen und die Schulterblätter zusammenführen. Eine einfache Grundübung für den ganzen Rücken.'),
  ('close-grip-cable-row', 'en', 'Close-Grip Cable Row', 'Seated, pull the close grip to your stomach and bring your shoulder blades together. A simple compound exercise for the whole back.'),
  ('close-grip-lat-pulldown', 'de', 'Latziehen mit engem Griff', 'Mit einem engen Griff zur oberen Brust ziehen. Durch den engen Griff arbeiten Latissimus und Arme über einen längeren Weg.'),
  ('close-grip-lat-pulldown', 'en', 'Close-Grip Lat Pulldown', 'Pull to your upper chest with a close grip. The close grip makes the lats and arms work over a longer range.'),
  ('concentration-curls', 'de', 'Konzentrations-Curls', 'Im Sitzen den Ellbogen an der Innenseite des Oberschenkels abstützen und langsam curlen. Kein Schwung möglich.'),
  ('concentration-curls', 'en', 'Concentration Curls', 'Seated, brace your elbow against the inside of your thigh and curl slowly. No momentum possible.'),
  ('cross-body-hammer-curls', 'de', 'Cross-Body Hammer-Curls', 'Jede Kurzhantel im neutralen Griff quer vor dem Körper zur gegenüberliegenden Schulter curlen. Aktiviert den Brachioradialis besonders stark.'),
  ('cross-body-hammer-curls', 'en', 'Cross-Body Hammer Curls', 'Curl each dumbbell with a neutral grip across your body toward the opposite shoulder. Activates the brachioradialis especially strongly.'),
  ('crunches', 'de', 'Crunches', 'In Rückenlage den Oberkörper einrollen, bis die Schulterblätter vom Boden abheben. Die einfachste Übung für den geraden Bauchmuskel.'),
  ('crunches', 'en', 'Crunches', 'Lying on your back, curl your upper body until your shoulder blades lift off the floor. The simplest exercise for the rectus abdominis.'),
  ('dead-bug', 'de', 'Dead Bug', 'In Rückenlage mit angehobenen Armen und Beinen abwechselnd einen Arm und das gegenüberliegende Bein strecken. Trainiert die Rumpfspannung, ohne den Rücken zu belasten.'),
  ('dead-bug', 'en', 'Dead Bug', 'Lying on your back with arms and legs raised, alternately extend one arm and the opposite leg. Trains core stability without loading the back.'),
  ('deadlifts', 'de', 'Kreuzheben', 'Die Stange mit geradem Rücken vom Boden heben. Der Rückenstrecker arbeitet hart, um die Wirbelsäule unter schwerer Last neutral zu halten.'),
  ('deadlifts', 'en', 'Deadlifts', 'Lift the bar from the floor with a straight back. The spinal erectors work hard to keep the spine neutral under heavy load.'),
  ('decline-bench-press', 'de', 'Negativ-Bankdrücken', 'Auf einer nach unten geneigten Bank drücken. Der Druckweg verläuft in Faserrichtung der unteren Brust.'),
  ('decline-bench-press', 'en', 'Decline Bench Press', 'Press on a downward-sloping bench. The pressing path follows the fibre direction of the lower chest.'),
  ('decline-crunches', 'de', 'Crunches auf der Negativbank', 'Auf der Negativbank den Oberkörper eingerollt nach oben bringen. Durch die Schräge ist der Weg länger und die Übung schwerer als am Boden.'),
  ('decline-crunches', 'en', 'Decline Crunches', 'Curl your upper body up on a decline bench. The incline makes the range longer and the exercise harder than on the floor.'),
  ('decline-push-ups', 'de', 'Liegestütze mit erhöhten Füßen', 'Liegestütze mit den Füßen auf einer Bank. Durch die Schräge arbeitet vor allem die obere Brust, und die Übung wird schwerer als normale Liegestütze.'),
  ('decline-push-ups', 'en', 'Decline Push-Ups', 'Push-ups with your feet on a bench. The angle shifts the work mainly to the upper chest and makes the exercise harder than regular push-ups.'),
  ('dumbbell-bench-press', 'de', 'Kurzhantel-Bankdrücken', 'Auf der Flachbank mit Kurzhanteln drücken. Größerer Bewegungsweg als mit der Langhantel und schonender für die Schultern.'),
  ('dumbbell-bench-press', 'en', 'Dumbbell Bench Press', 'Press with dumbbells on a flat bench. Greater range of motion than with a barbell and easier on the shoulders.'),
  ('dumbbell-calf-raises', 'de', 'Wadenheben mit Kurzhanteln', 'Wadenheben im Stehen mit Kurzhanteln in den Händen. Funktioniert ohne Maschine.'),
  ('dumbbell-calf-raises', 'en', 'Dumbbell Calf Raises', 'Standing calf raises with dumbbells in your hands. Works without a machine.'),
  ('dumbbell-flys', 'de', 'Flys mit Kurzhanteln', 'Auf der Flachbank die Kurzhanteln in einem weiten Bogen absenken und über der Brust wieder zusammenführen. Dehnt die Brust und trainiert sie ohne viel Trizeps.'),
  ('dumbbell-flys', 'en', 'Dumbbell Flys', 'On a flat bench, lower the dumbbells in a wide arc and bring them back together over your chest. Stretches the chest and trains it without much triceps.'),
  ('dumbbell-kickbacks', 'de', 'Kurzhantel-Kickbacks', 'Vorgebeugt, Oberarm parallel zum Boden, die Kurzhantel nach hinten strecken und oben kurz halten. Leichtes Gewicht, volle Streckung.'),
  ('dumbbell-kickbacks', 'en', 'Dumbbell Kickbacks', 'Bent over, upper arm parallel to the floor, extend the dumbbell back and hold briefly at the top. Light weight, full extension.'),
  ('dumbbell-lateral-raises', 'de', 'Seitheben mit Kurzhanteln', 'Die Kurzhanteln mit leicht gebeugten Ellbogen seitlich bis auf Schulterhöhe heben. Die wichtigste Übung für breitere Schultern.'),
  ('dumbbell-lateral-raises', 'en', 'Dumbbell Lateral Raises', 'Raise the dumbbells out to the sides to shoulder height with slightly bent elbows. The most important exercise for wider shoulders.'),
  ('dumbbell-lunges', 'de', 'Ausfallschritte mit Kurzhanteln', 'Einen großen Schritt nach vorn machen, das hintere Knie Richtung Boden senken und wieder zurückdrücken. Trainiert Beine und Gesäß.'),
  ('dumbbell-lunges', 'en', 'Dumbbell Lunges', 'Take a big step forward, lower your back knee toward the floor and push back up. Trains the legs and glutes.'),
  ('dumbbell-pullover', 'de', 'Kurzhantel-Pullover', 'Auf der Bank liegend eine Kurzhantel mit fast gestreckten Armen hinter den Kopf absenken und wieder über die Brust führen. Trainiert Brust und Latissimus zugleich.'),
  ('dumbbell-pullover', 'en', 'Dumbbell Pullover', 'Lying on the bench, lower a dumbbell behind your head with almost straight arms and bring it back over your chest. Trains the chest and lats at the same time.'),
  ('dumbbell-shrugs', 'de', 'Shrugs mit Kurzhanteln', 'Die Schultern gerade Richtung Ohren ziehen, kurz halten und langsam absenken. Nicht mit den Schultern kreisen.'),
  ('dumbbell-shrugs', 'en', 'Dumbbell Shrugs', 'Pull your shoulders straight up toward your ears, hold briefly and lower slowly. Don''t roll your shoulders.'),
  ('dumbbell-side-bends', 'de', 'Seitbeugen mit Kurzhantel', 'Mit einer Hantel in einer Hand zur Seite neigen und mit der gegenüberliegenden Seite wieder aufrichten.'),
  ('dumbbell-side-bends', 'en', 'Dumbbell Side Bends', 'With a dumbbell in one hand, lean to the side and come back up using the opposite side.'),
  ('ez-bar-french-press', 'de', 'French Press mit SZ-Stange', 'Auf der Bank liegend die Stange hinter den Kopf absenken statt zur Stirn. Dadurch steht der Oberarm schräg nach hinten und der lange Kopf wird stärker gedehnt.'),
  ('ez-bar-french-press', 'en', 'EZ-Bar French Press', 'Lying on the bench, lower the bar behind your head instead of to your forehead. This angles the upper arm back and stretches the long head more.'),
  ('ez-bar-reverse-curls', 'de', 'Reverse Curls mit SZ-Stange', 'Curls im Obergriff. Der Bizeps hat hier eine schlechte Hebelwirkung, deshalb landet die Last beim Brachialis und im Unterarm.'),
  ('ez-bar-reverse-curls', 'en', 'EZ-Bar Reverse Curls', 'Curls with an overhand grip. The biceps has poor leverage here, so the load goes to the brachialis and forearms.'),
  ('face-pulls', 'de', 'Face Pulls', 'Das Seil mit hohen Ellbogen zum Gesicht ziehen, bis die Hände neben den Ohren sind. Trainiert die hintere Schulter und hält das Schultergelenk gesund.'),
  ('face-pulls', 'en', 'Face Pulls', 'Pull the rope to your face with high elbows until your hands are next to your ears. Trains the rear delts and keeps the shoulder joint healthy.'),
  ('farmers-walk', 'de', 'Farmer’s Walk', 'Schwere Gewichte aufnehmen und aufrecht damit gehen. Baut eine starke Griffkraft und Ausdauer im Unterarm auf.'),
  ('farmers-walk', 'en', 'Farmer’s Walk', 'Pick up heavy weights and walk tall with them. Builds strong grip and forearm endurance.'),
  ('front-raises', 'de', 'Frontheben', 'Das Gewicht mit fast gestreckten Armen vor dem Körper bis auf Augenhöhe heben. Isoliert die vordere Schulter.'),
  ('front-raises', 'en', 'Front Raises', 'Raise the weight in front of you with almost straight arms up to eye level. Isolates the front delts.'),
  ('front-squats', 'de', 'Frontkniebeugen', 'Kniebeugen mit der Stange vorn auf den Schultern. Der Oberkörper bleibt aufrechter, die Knie gehen weiter nach vorn – mehr Arbeit für den Quadrizeps.'),
  ('front-squats', 'en', 'Front Squats', 'Squats with the bar in front on your shoulders. The upper body stays more upright and the knees travel further forward – more work for the quads.'),
  ('glute-bridge', 'de', 'Glute Bridge', 'Wie Hip Thrusts, aber mit dem Rücken auf dem Boden. Kürzerer Bewegungsweg, ideal zum Einstieg oder als Aktivierung vor Kniebeugen.'),
  ('glute-bridge', 'en', 'Glute Bridge', 'Like hip thrusts, but with your back on the floor. Shorter range of motion, ideal for beginners or as activation before squats.'),
  ('goblet-squats', 'de', 'Goblet Squats', 'Eine Kettlebell vor der Brust halten und tief in die Hocke gehen. Das Gewicht vorne hält den Oberkörper aufrecht – ideal, um saubere Kniebeugen zu lernen.'),
  ('goblet-squats', 'en', 'Goblet Squats', 'Hold a kettlebell in front of your chest and squat deep. The weight in front keeps your upper body upright – ideal for learning clean squats.'),
  ('good-mornings', 'de', 'Good Mornings', 'Mit der Stange auf dem oberen Rücken und leicht gebeugten Knien in der Hüfte nach vorn beugen, bis der Oberkörper fast waagerecht ist, dann aufrichten.'),
  ('good-mornings', 'en', 'Good Mornings', 'With the bar on your upper back and knees slightly bent, hinge forward at the hips until your upper body is almost horizontal, then stand back up.'),
  ('hack-squats', 'de', 'Hackenschmidt-Kniebeugen', 'Kniebeugen an der Maschine mit hüftbreitem Stand. Die geführte Bahn erlaubt schweres, sicheres Training bis tief nach unten.'),
  ('hack-squats', 'en', 'Hack Squats', 'Machine squats with a hip-width stance. The guided path allows heavy, safe training all the way down.'),
  ('hammer-curls', 'de', 'Hammer-Curls', 'Curls im neutralen Griff (Handflächen zeigen zueinander). Der Bizeps verliert seine Drehfunktion, also übernimmt der Brachialis mehr Arbeit.'),
  ('hammer-curls', 'en', 'Hammer Curls', 'Curls with a neutral grip (palms facing each other). The biceps loses its rotating role, so the brachialis takes on more work.'),
  ('hanging-knee-raises', 'de', 'Knieheben im Hang', 'An der Stange hängen und die Knie über Hüfthöhe ziehen. Die Hüftbeuger heben, der Bauch stabilisiert.'),
  ('hanging-knee-raises', 'en', 'Hanging Knee Raises', 'Hang from the bar and pull your knees above hip height. The hip flexors lift, the abs stabilise.'),
  ('hanging-leg-raises', 'de', 'Beinheben im Hang', 'An der Stange hängen und die Beine heben, dabei das Becken nach oben einrollen. Nicht schwingen – die Kontrolle macht die Übung wirksam.'),
  ('hanging-leg-raises', 'en', 'Hanging Leg Raises', 'Hang from the bar and raise your legs while curling your pelvis up. Don''t swing – control is what makes the exercise work.'),
  ('heel-elevated-squats', 'de', 'Kniebeugen mit erhöhten Fersen', 'Fersen auf einer Erhöhung, aufrechter Oberkörper, tief nach unten mit den Knien weit über den Zehen.'),
  ('heel-elevated-squats', 'en', 'Heel-Elevated Squats', 'Heels raised, upper body upright, go deep with your knees travelling far over your toes.'),
  ('high-to-low-cable-flys', 'de', 'Cable Flys von oben nach unten', 'Die Griffe vom oberen Kabelzug in einem Bogen nach vorn unten vor dem Bauch zusammenführen. Isoliert die untere Brust.'),
  ('high-to-low-cable-flys', 'en', 'High-to-Low Cable Flys', 'Bring the handles from the high pulley forward and down in an arc until they meet in front of your stomach. Isolates the lower chest.'),
  ('hip-abduction-machine', 'de', 'Abduktoren-Maschine', 'Die Polster mit den Knien auseinanderdrücken. Leicht nach vorn gelehnt arbeitet das Gesäß stärker mit.'),
  ('hip-abduction-machine', 'en', 'Hip Abduction Machine', 'Push the pads apart with your knees. Leaning slightly forward brings the glutes in more.'),
  ('hip-adduction-machine', 'de', 'Adduktoren-Maschine', 'Die Polster aus einer weiten Position zusammendrücken. Den Rückweg kontrollieren, um eine gute Dehnung zu bekommen.'),
  ('hip-adduction-machine', 'en', 'Hip Adduction Machine', 'Squeeze the pads together from a wide position. Control the way back to get a good stretch.'),
  ('incline-barbell-bench-press', 'de', 'Schrägbankdrücken mit der Langhantel', 'Bank auf etwa 30° stellen und die Stange zur oberen Brust knapp unter dem Schlüsselbein absenken. Die schwere Grundübung für die obere Brust.'),
  ('incline-barbell-bench-press', 'en', 'Incline Barbell Bench Press', 'Set the bench to about 30° and lower the bar to your upper chest just below the collarbone. The heavy compound exercise for the upper chest.'),
  ('incline-cable-flys', 'de', 'Cable Flys auf der Schrägbank', 'Auf der Schrägbank zwischen zwei Kabelzügen die Arme im Bogen über der Brust zusammenführen. Der Zug bleibt über die ganze Bewegung gleichmäßig auf der oberen Brust.'),
  ('incline-cable-flys', 'en', 'Incline Cable Flys', 'On an incline bench between two cables, bring your arms together over your chest in an arc. The pull stays evenly on the upper chest through the whole movement.'),
  ('incline-dumbbell-curls', 'de', 'Schrägbank-Curls', 'Auf einer Bank bei etwa 45° zurücklehnen, Arme hängen gerade nach unten. Die Arme sind hinter dem Körper, das dehnt den langen Kopf besonders stark.'),
  ('incline-dumbbell-curls', 'en', 'Incline Dumbbell Curls', 'Lean back on a bench at about 45° with your arms hanging straight down. The arms are behind the body, which stretches the long head especially strongly.'),
  ('incline-dumbbell-flys', 'de', 'Schrägbank-Flys', 'Auf der Schrägbank die Kurzhanteln mit leicht gebeugten Armen weit nach außen absenken und wieder zusammenführen. Starke Dehnung für die obere Brust.'),
  ('incline-dumbbell-flys', 'en', 'Incline Dumbbell Flys', 'On an incline bench, lower the dumbbells wide with slightly bent arms and bring them back together. A strong stretch for the upper chest.'),
  ('incline-dumbbell-press', 'de', 'Schrägbankdrücken mit Kurzhanteln', 'Wie mit der Langhantel, aber jede Seite arbeitet für sich und die Hanteln dürfen unten etwas tiefer gehen. Mehr Dehnung, gut gegen Seitenunterschiede.'),
  ('incline-dumbbell-press', 'en', 'Incline Dumbbell Press', 'Like with the barbell, but each side works on its own and the dumbbells can go a little deeper. More stretch, good against side imbalances.'),
  ('incline-reverse-flys', 'de', 'Reverse Flys auf der Schrägbank', 'Bäuchlings auf der Schrägbank die Kurzhanteln seitlich nach oben heben. Die Bank stützt den Oberkörper, so lässt sich kaum mit Schwung arbeiten.'),
  ('incline-reverse-flys', 'en', 'Incline Reverse Flys', 'Lying face down on an incline bench, raise the dumbbells out to the sides. The bench supports your upper body, so there''s hardly any room for momentum.'),
  ('incline-y-raises', 'de', 'Y-Raises auf der Schrägbank', 'Bäuchlings auf der Schrägbank leichte Kurzhanteln in Y-Form schräg nach vorne oben heben. Kräftigt den unteren Trapez, der die Schulterblätter nach unten zieht.'),
  ('incline-y-raises', 'en', 'Incline Y-Raises', 'Lying face down on an incline bench, raise light dumbbells forward and up in a Y shape. Strengthens the lower traps, which pull the shoulder blades down.'),
  ('inverted-rows', 'de', 'Rudern im Hang', 'Unter einer Stange hängend den gestreckten Körper zur Stange ziehen. Rudern mit dem eigenen Körpergewicht – je flacher, desto schwerer.'),
  ('inverted-rows', 'en', 'Inverted Rows', 'Hanging under a bar, pull your straight body up to the bar. Rowing with your own body weight – the flatter, the harder.'),
  ('kettlebell-swing', 'de', 'Kettlebell Swing', 'Die Kettlebell mit einer kraftvollen Hüftstreckung nach vorne bis auf Brusthöhe schwingen. Trainiert die ganze Körperrückseite und bringt den Puls hoch.'),
  ('kettlebell-swing', 'en', 'Kettlebell Swing', 'Swing the kettlebell forward to chest height with a powerful hip extension. Trains the entire back of the body and gets your heart rate up.'),
  ('kneeling-cable-crunches', 'de', 'Kniende Kabel-Crunches', 'Vor dem oberen Kabelzug knien und die Rippen Richtung Hüfte einrollen. Lässt sich anders als die meisten Bauchübungen gut mit Gewicht steigern.'),
  ('kneeling-cable-crunches', 'en', 'Kneeling Cable Crunches', 'Kneel in front of the high pulley and curl your ribs toward your hips. Unlike most ab exercises, easy to progress with weight.'),
  ('landmine-press', 'de', 'Landmine Press', 'Eine Langhantel, deren Ende in einer Ecke oder Landmine-Halterung steckt, im Stand schräg nach vorne oben drücken. Schont die Schultern und trainiert obere Brust und vordere Schulter.'),
  ('landmine-press', 'en', 'Landmine Press', 'Standing, press a barbell whose end sits in a corner or landmine holder forward and up at an angle. Easy on the shoulders and trains the upper chest and front delts.'),
  ('lat-pulldown', 'de', 'Latziehen', 'Die Stange zur oberen Brust ziehen und dabei die Ellbogen nach unten führen. Eine Klimmzug-Alternative für jedes Kraftniveau.'),
  ('lat-pulldown', 'en', 'Lat Pulldown', 'Pull the bar to your upper chest, driving your elbows down. A pull-up alternative for every strength level.'),
  ('leg-press-calf-raises', 'de', 'Wadendrücken an der Beinpresse', 'Die Plattform mit gestreckten Beinen nur mit den Fußballen drücken. So lassen sich die Waden schwer und sicher belasten.'),
  ('leg-press-calf-raises', 'en', 'Leg Press Calf Raises', 'Press the platform with straight legs using only the balls of your feet. This lets you load the calves heavily and safely.'),
  ('low-to-high-cable-flys', 'de', 'Cable Flys von unten nach oben', 'Die Griffe vom unteren Kabelzug in einem Bogen nach vorn oben bis auf Augenhöhe zusammenführen. Folgt genau der Faserrichtung der oberen Brust.'),
  ('low-to-high-cable-flys', 'en', 'Low-to-High Cable Flys', 'Bring the handles from the low pulley forward and up in an arc to eye level. Follows the fibre direction of the upper chest exactly.'),
  ('lying-leg-curls', 'de', 'Liegender Beinbeuger', 'Bäuchlings liegend die Fersen zum Gesäß ziehen. Klassische Isolationsübung für die Oberschenkelrückseite.'),
  ('lying-leg-curls', 'en', 'Lying Leg Curls', 'Lying face down, pull your heels toward your glutes. A classic isolation exercise for the back of the thighs.'),
  ('lying-leg-raises', 'de', 'Beinheben im Liegen', 'Auf dem Rücken liegend die gestreckten Beine bis in die Senkrechte heben und langsam wieder absenken. Fordert den unteren Bauch und die Hüftbeuger.'),
  ('lying-leg-raises', 'en', 'Lying Leg Raises', 'Lying on your back, raise your straight legs to vertical and lower them slowly. Works the lower abs and hip flexors.'),
  ('machine-lateral-raises', 'de', 'Seitheben an der Maschine', 'An der Maschine die Arme gegen die Polster seitlich bis auf Schulterhöhe heben. Gleichmäßiger Widerstand über die ganze Bewegung und leicht zu lernen.'),
  ('machine-lateral-raises', 'en', 'Machine Lateral Raises', 'On the machine, raise your arms against the pads out to shoulder height. Even resistance over the whole movement and easy to learn.'),
  ('machine-row', 'de', 'Rudern an der Maschine', 'Mit der Brust am Polster die Griffe zum Körper ziehen. Das Polster stützt den Oberkörper, so arbeitet ganz der Rücken.'),
  ('machine-row', 'en', 'Machine Row', 'With your chest on the pad, pull the handles toward your body. The pad supports your upper body, so the back does all the work.'),
  ('machine-shoulder-press', 'de', 'Schulterpresse an der Maschine', 'Die Griffe der Maschine von Schulterhöhe nach oben drücken. Die geführte Bewegung macht die Übung einfach und sicher.'),
  ('machine-shoulder-press', 'en', 'Machine Shoulder Press', 'Press the machine''s handles up from shoulder height. The guided movement makes the exercise simple and safe.'),
  ('narrow-stance-leg-press', 'de', 'Beinpresse mit engem Stand', 'Füße eng und eher tief auf die Plattform stellen. Belastet den Quadrizeps schwer, ohne die Wirbelsäule zu stauchen.'),
  ('narrow-stance-leg-press', 'en', 'Narrow-Stance Leg Press', 'Place your feet close together and fairly low on the platform. Loads the quads heavily without compressing the spine.'),
  ('neck-extensions', 'de', 'Nackenstrecken', 'Bäuchlings auf der Bank den Kopf aus der eingezogenen Position bis in die Neutralstellung heben. Sehr leicht beginnen – der Nacken gewöhnt sich langsam an Belastung.'),
  ('neck-extensions', 'en', 'Neck Extensions', 'Lying face down on the bench, raise your head from the tucked position to neutral. Start very light – the neck adapts to load slowly.'),
  ('nordic-hamstring-curls', 'de', 'Nordic Hamstring Curls', 'Knien, Füße fixiert, und den Oberkörper so langsam wie möglich nach vorn absenken. Nachweislich wirksam gegen Verletzungen der Oberschenkelrückseite.'),
  ('nordic-hamstring-curls', 'en', 'Nordic Hamstring Curls', 'Kneeling with your feet anchored, lower your upper body forward as slowly as possible. Proven to help prevent hamstring injuries.'),
  ('one-arm-dumbbell-row', 'de', 'Einarmiges Kurzhantelrudern', 'Auf der Bank abstützen und die Kurzhantel Richtung Hüfte ziehen. Zur Hüfte statt zur Brust zu ziehen betont den Latissimus.'),
  ('one-arm-dumbbell-row', 'en', 'One-Arm Dumbbell Row', 'Brace on the bench and pull the dumbbell toward your hip. Pulling to the hip instead of the chest emphasises the lats.'),
  ('overhead-cable-triceps-extension', 'de', 'Trizepsstrecken über Kopf am Kabelzug', 'Mit dem Rücken zum Kabelzug das Seil über den Kopf strecken. Die Position über Kopf dehnt den langen Kopf maximal.'),
  ('overhead-cable-triceps-extension', 'en', 'Overhead Cable Triceps Extension', 'With your back to the cable, extend the rope overhead. The overhead position stretches the long head to the maximum.'),
  ('overhead-dumbbell-triceps-extension', 'de', 'Kurzhantel-Trizepsstrecken über Kopf', 'Eine Kurzhantel mit beiden Händen hinter den Kopf absenken und wieder strecken. Ellbogen zeigen nach vorn oben.'),
  ('overhead-dumbbell-triceps-extension', 'en', 'Overhead Dumbbell Triceps Extension', 'Lower one dumbbell behind your head with both hands and extend again. Elbows point forward and up.'),
  ('pallof-press', 'de', 'Pallof Press', 'Seitlich zum Kabelzug stehen und den Griff gerade von der Brust wegdrücken, ohne dass sich der Oberkörper mitdreht.'),
  ('pallof-press', 'en', 'Pallof Press', 'Stand side-on to the cable and press the handle straight away from your chest without letting your upper body rotate.'),
  ('parallel-bar-dips', 'de', 'Dips am Barren', 'Oberkörper aufrecht halten, um den Trizeps statt der Brust zu betonen. Bei vielen Wiederholungen mit Gewichtsgürtel steigern.'),
  ('parallel-bar-dips', 'en', 'Parallel Bar Dips', 'Keep your upper body upright to emphasise the triceps rather than the chest. Add a dip belt once you can do many reps.'),
  ('pec-deck-machine', 'de', 'Butterfly-Maschine', 'Die Griffe auf Brusthöhe vor dem Körper zusammenführen und langsam zurück in die Dehnung. Isoliert die Brust ohne Trizeps.'),
  ('pec-deck-machine', 'en', 'Pec Deck Machine', 'Bring the handles together in front of you at chest height and return slowly into the stretch. Isolates the chest without the triceps.'),
  ('plank', 'de', 'Unterarmstütz (Plank)', 'Auf Unterarmen und Zehen den Körper gerade halten. Trainiert den ganzen Rumpf darin, die Wirbelsäule stabil zu halten.'),
  ('plank', 'en', 'Plank', 'Hold your body straight on your forearms and toes. Trains the whole core to keep the spine stable.'),
  ('plate-neck-curls', 'de', 'Nacken-Curls mit Hantelscheibe', 'Rückenlage mit dem Kopf über dem Bankende, eine leichte Scheibe auf der Stirn (mit Handtuch). Das Kinn zur Brust ziehen und langsam zurück.'),
  ('plate-neck-curls', 'en', 'Plate Neck Curls', 'Lying on your back with your head over the end of the bench, a light plate on your forehead (with a towel). Pull your chin to your chest and return slowly.'),
  ('preacher-curls', 'de', 'Scott-Curls', 'Oberarme auf dem schrägen Polster vor dem Körper. In dieser Position kann der lange Kopf weniger helfen, der kurze Kopf übernimmt.'),
  ('preacher-curls', 'en', 'Preacher Curls', 'Upper arms on the angled pad in front of your body. In this position the long head can help less, so the short head takes over.'),
  ('pull-ups', 'de', 'Klimmzüge', 'Obergriff etwas breiter als schulterbreit, hochziehen bis das Kinn über der Stange ist. Die Maßstab-Übung für den Rücken mit dem eigenen Körpergewicht.'),
  ('pull-ups', 'en', 'Pull-Ups', 'Overhand grip slightly wider than shoulder width, pull up until your chin is over the bar. The benchmark bodyweight exercise for the back.'),
  ('push-ups', 'de', 'Liegestütze', 'Hände etwas breiter als schulterbreit, Körper bildet eine gerade Linie. Lässt sich von Knie-Liegestützen bis zu Varianten mit Zusatzgewicht steigern.'),
  ('push-ups', 'en', 'Push-Ups', 'Hands slightly wider than shoulder width, body in a straight line. Can be progressed from knee push-ups to weighted variations.'),
  ('rack-pulls', 'de', 'Rack Pulls', 'Kreuzheben aus dem Rack, die Stange liegt etwa auf Kniehöhe. Der kürzere Weg erlaubt mehr Gewicht für den oberen Teil der Bewegung.'),
  ('rack-pulls', 'en', 'Rack Pulls', 'Deadlifts from the rack with the bar at about knee height. The shorter range allows more weight for the top part of the movement.'),
  ('reclined-leg-extensions', 'de', 'Beinstrecker, zurückgelehnt', 'Beinstrecker mit nach hinten gelehntem Oberkörper. Die gestreckte Hüfte dehnt den Rectus femoris und lässt ihn mehr arbeiten als bei Kniebeugen.'),
  ('reclined-leg-extensions', 'en', 'Reclined Leg Extensions', 'Leg extensions with your upper body leaning back. The extended hip stretches the rectus femoris and makes it work harder than in squats.'),
  ('reverse-cable-flys', 'de', 'Reverse Cable Flys', 'Die Kabel über Kreuz greifen und mit gestreckten Armen auf Schulterhöhe nach außen ziehen. Konstante Spannung auf der hinteren Schulter.'),
  ('reverse-cable-flys', 'en', 'Reverse Cable Flys', 'Grab the cables crossed over and pull outward at shoulder height with straight arms. Constant tension on the rear delts.'),
  ('reverse-crunches', 'de', 'Reverse Crunches', 'In Rückenlage die angewinkelten Beine heben und das Becken vom Boden einrollen. Betont den unteren Teil des Bauchs.'),
  ('reverse-crunches', 'en', 'Reverse Crunches', 'Lying on your back, raise your bent legs and curl your pelvis off the floor. Emphasises the lower part of the abs.'),
  ('reverse-grip-triceps-pushdown', 'de', 'Trizepsdrücken im Untergriff', 'Trizepsdrücken mit Handflächen nach oben. Der Untergriff betont den mittleren Kopf.'),
  ('reverse-grip-triceps-pushdown', 'en', 'Reverse-Grip Triceps Pushdown', 'Triceps pushdown with your palms facing up. The underhand grip emphasises the medial head.'),
  ('reverse-hyperextensions', 'de', 'Reverse Hyperextensions', 'Bäuchlings auf der Bank, Beine hängen frei. Die gestreckten Beine aus dem Gesäß nach hinten oben heben, oben kurz halten.'),
  ('reverse-hyperextensions', 'en', 'Reverse Hyperextensions', 'Lying face down on the bench with your legs hanging free. Raise your straight legs back and up from the glutes and hold briefly at the top.'),
  ('reverse-nordic-curls', 'de', 'Reverse Nordic Curls', 'Kniend den geraden Oberkörper langsam nach hinten neigen und wieder aufrichten. Dehnt und kräftigt den vorderen Oberschenkel stark.'),
  ('reverse-nordic-curls', 'en', 'Reverse Nordic Curls', 'Kneeling, slowly lean your straight upper body back and come back up. Strongly stretches and strengthens the front of the thigh.'),
  ('reverse-pec-deck', 'de', 'Reverse Butterfly', 'Mit dem Gesicht zur Maschine die Griffe mit gestreckten Armen nach hinten führen. Isoliert die hintere Schulter, die bei Druckübungen kaum mitarbeitet.'),
  ('reverse-pec-deck', 'en', 'Reverse Pec Deck', 'Facing the machine, move the handles back with straight arms. Isolates the rear delts, which barely work in pressing exercises.'),
  ('reverse-wrist-curls', 'de', 'Reverse Handgelenk-Curls', 'Unterarme auf den Oberschenkeln, Handflächen nach unten. Den Handrücken Richtung Decke heben. Leichtes Gewicht, volle Bewegung.'),
  ('reverse-wrist-curls', 'en', 'Reverse Wrist Curls', 'Forearms on your thighs, palms down. Raise the back of your hand toward the ceiling. Light weight, full range.'),
  ('romanian-deadlifts', 'de', 'Rumänisches Kreuzheben', 'Mit leicht gebeugten Knien die Hüfte nach hinten schieben, bis eine starke Dehnung kommt, dann die Hüfte nach vorn bringen und aufrichten.'),
  ('romanian-deadlifts', 'en', 'Romanian Deadlifts', 'With slightly bent knees, push your hips back until you feel a strong stretch, then bring your hips forward and stand up.'),
  ('rope-hammer-curls', 'de', 'Hammer-Curls am Seilzug', 'Hammer-Curls am unteren Kabelzug mit Seil. Konstante Spannung und schonend für die Handgelenke.'),
  ('rope-hammer-curls', 'en', 'Rope Hammer Curls', 'Hammer curls on the low pulley with a rope. Constant tension and easy on the wrists.'),
  ('rope-triceps-pushdown', 'de', 'Trizepsdrücken am Seil', 'Ellbogen am Körper fixiert, das Seil nach unten drücken und die Enden unten auseinanderziehen. Der Klassiker für das Trizeps-Hufeisen.'),
  ('rope-triceps-pushdown', 'en', 'Rope Triceps Pushdown', 'Elbows fixed at your sides, push the rope down and pull the ends apart at the bottom. The classic for the triceps horseshoe.'),
  ('russian-twist', 'de', 'Russian Twist', 'Im Sitzen leicht zurückgelehnt den Oberkörper von Seite zu Seite drehen. Trainiert die Rotation des Rumpfes.'),
  ('russian-twist', 'en', 'Russian Twist', 'Seated and leaning back slightly, rotate your upper body from side to side. Trains core rotation.'),
  ('scapular-pull-ups', 'de', 'Schulterblatt-Klimmzüge', 'An der Stange hängen und nur die Schulterblätter nach unten ziehen, die Arme bleiben gestreckt. Der Körper hebt sich dabei ein paar Zentimeter.'),
  ('scapular-pull-ups', 'en', 'Scapular Pull-Ups', 'Hang from the bar and only pull your shoulder blades down while your arms stay straight. Your body rises a few centimetres.'),
  ('scapular-push-ups', 'de', 'Schulterblatt-Liegestütze', 'In der Liegestützposition mit gestreckten Armen nur die Schulterblätter zusammenführen und wieder auseinanderschieben. Kräftigt den Sägezahnmuskel und schult die Kontrolle der Schulterblätter.'),
  ('scapular-push-ups', 'en', 'Scapular Push-Ups', 'In the push-up position with straight arms, only bring your shoulder blades together and push them apart again. Strengthens the serratus anterior and trains shoulder blade control.'),
  ('seated-barbell-shoulder-press', 'de', 'Schulterdrücken mit der Langhantel im Sitzen', 'Auf einer Bank mit Rückenlehne die Langhantel von der oberen Brust über den Kopf drücken. Die Lehne stützt den Rücken, so landet viel Gewicht auf den Schultern.'),
  ('seated-barbell-shoulder-press', 'en', 'Seated Barbell Shoulder Press', 'On a bench with a backrest, press the barbell from your upper chest overhead. The backrest supports your back, so a lot of weight goes to the shoulders.'),
  ('seated-calf-raises', 'de', 'Wadenheben im Sitzen', 'Mit gebeugten Knien ist der Zwillingswadenmuskel entspannt, deshalb macht der Soleus den Großteil der Arbeit.'),
  ('seated-calf-raises', 'en', 'Seated Calf Raises', 'With bent knees the gastrocnemius is slack, so the soleus does most of the work.'),
  ('seated-dumbbell-shoulder-press', 'de', 'Kurzhantel-Schulterdrücken sitzend', 'Mit Rückenlehne die Kurzhanteln von Ohrhöhe über den Kopf drücken. Die Lehne nimmt dem unteren Rücken Arbeit ab.'),
  ('seated-dumbbell-shoulder-press', 'en', 'Seated Dumbbell Shoulder Press', 'With back support, press the dumbbells overhead from ear height. The backrest takes work off your lower back.'),
  ('seated-leg-curls', 'de', 'Sitzender Beinbeuger', 'Im Sitzen sind die Beinbeuger an der Hüfte vorgedehnt. Dadurch ist diese Variante wirksamer als der liegende Beinbeuger.'),
  ('seated-leg-curls', 'en', 'Seated Leg Curls', 'Seated, the hamstrings are pre-stretched at the hip. That makes this variation more effective than the lying leg curl.'),
  ('side-lying-external-rotation', 'de', 'Außenrotation in Seitenlage', 'Auf der Seite liegend, mit einem Handtuch unter dem Ellbogen, die Kurzhantel nach oben drehen. Eine klassische Übung zur Vorbeugung von Schulterproblemen.'),
  ('side-lying-external-rotation', 'en', 'Side-Lying External Rotation', 'Lying on your side with a towel under your elbow, rotate the dumbbell upward. A classic exercise for preventing shoulder problems.'),
  ('side-plank', 'de', 'Seitstütz', 'Auf einem Unterarm in einer geraden Linie halten. Steigern durch Anheben des oberen Beins oder Hüftsenken.'),
  ('side-plank', 'en', 'Side Plank', 'Hold a straight line on one forearm. Progress by raising the top leg or doing hip dips.'),
  ('single-leg-romanian-deadlift', 'de', 'Einbeiniges Rumänisches Kreuzheben', 'Auf einem Bein stehend nach vorn beugen, das freie Bein geht nach hinten. Der mittlere Gesäßmuskel arbeitet die ganze Zeit, damit das Becken nicht wegkippt.'),
  ('single-leg-romanian-deadlift', 'en', 'Single-Leg Romanian Deadlift', 'Standing on one leg, hinge forward while the free leg goes back. The gluteus medius works the whole time to keep the pelvis from tipping.'),
  ('smith-machine-incline-press', 'de', 'Schrägbankdrücken an der Multipresse', 'Die geführte Stange läuft auf einer festen Bahn, so kannst du dich ganz auf die obere Brust konzentrieren. Gut geeignet, um auch ohne Partner sicher schwer zu trainieren.'),
  ('smith-machine-incline-press', 'en', 'Smith Machine Incline Press', 'The guided bar runs on a fixed path, so you can focus fully on your upper chest. Well suited to training heavy safely, even without a partner.'),
  ('smith-machine-shoulder-press', 'de', 'Schulterdrücken an der Multipresse', 'Im Sitzen die geführte Stange der Multipresse über den Kopf drücken. Die feste Bahn nimmt dir das Ausbalancieren ab.'),
  ('smith-machine-shoulder-press', 'en', 'Smith Machine Shoulder Press', 'Seated, press the guided bar of the Smith machine overhead. The fixed path takes the balancing off you.'),
  ('smith-machine-squats', 'de', 'Kniebeugen an der Multipresse', 'Kniebeugen mit der geführten Stange der Multipresse. Die feste Bahn nimmt das Ausbalancieren ab, so kannst du dich ganz auf die Beine konzentrieren.'),
  ('smith-machine-squats', 'en', 'Smith Machine Squats', 'Squats with the guided bar of the Smith machine. The fixed path takes away the balancing, so you can focus fully on your legs.'),
  ('standing-calf-raises', 'de', 'Wadenheben im Stehen', 'Mit gestreckten Knien so hoch wie möglich auf die Zehen gehen, kurz halten und tief in die Dehnung absenken.'),
  ('standing-calf-raises', 'en', 'Standing Calf Raises', 'With straight knees, rise as high as possible onto your toes, hold briefly and lower deep into the stretch.'),
  ('standing-leg-curls', 'de', 'Stehender Beinbeuger', 'An der Maschine stehend ein Bein gegen das Polster zum Gesäß beugen. Trainiert jede Seite einzeln.'),
  ('standing-leg-curls', 'en', 'Standing Leg Curls', 'Standing at the machine, curl one leg against the pad toward your glutes. Trains each side individually.'),
  ('standing-overhead-press', 'de', 'Schulterdrücken im Stand', 'Die Stange vom Schlüsselbein bis über den Kopf drücken, dabei Gesäß anspannen, um kein Hohlkreuz zu machen. Schwere Grundübung für die vordere Schulter.'),
  ('standing-overhead-press', 'en', 'Standing Overhead Press', 'Press the bar from your collarbone to overhead, squeezing your glutes to avoid arching your back. A heavy compound exercise for the front delts.'),
  ('step-ups', 'de', 'Step-ups', 'Mit einem Bein auf eine Bank steigen und dich mit diesem Bein nach oben drücken. Trainiert jedes Bein einzeln und verbessert das Gleichgewicht.'),
  ('step-ups', 'en', 'Step-Ups', 'Step onto a bench with one leg and push yourself up with that leg. Trains each leg individually and improves balance.'),
  ('stiff-leg-deadlifts', 'de', 'Kreuzheben mit gestreckten Beinen', 'Wie Rumänisches Kreuzheben, aber mit fast gestreckten Knien. Dehnt die Beinbeuger noch stärker.'),
  ('stiff-leg-deadlifts', 'en', 'Stiff-Leg Deadlifts', 'Like Romanian deadlifts, but with almost straight knees. Stretches the hamstrings even more.'),
  ('sumo-squats', 'de', 'Sumo-Kniebeugen', 'Kniebeuge mit breitem Stand und nach außen gedrehten Füßen. Die breite Position belastet die Adduktoren über einen großen Bewegungsweg.'),
  ('sumo-squats', 'en', 'Sumo Squats', 'Squat with a wide stance and feet turned out. The wide position loads the adductors over a large range of motion.'),
  ('t-bar-row', 'de', 'T-Bar-Rudern', 'Vorgebeugt das Ende einer Langhantel mit einem Griff zur Brust ziehen. Erlaubt schweres Rudern für den ganzen oberen Rücken.'),
  ('t-bar-row', 'en', 'T-Bar Row', 'Bent over, pull the end of a barbell to your chest with a handle. Allows heavy rowing for the entire upper back.'),
  ('tibialis-raises', 'de', 'Reverse Calf Raises', 'Mit den Fersen auf einer Erhöhung stehen, die Fußballen ragen darüber hinaus, und die Fußspitzen nach oben ziehen. Trainiert den Schienbeinmuskel.'),
  ('tibialis-raises', 'en', 'Tibialis Raises', 'Stand with your heels on a raised edge and the balls of your feet hanging over, then pull your toes up. Trains the tibialis anterior.'),
  ('trap-bar-deadlifts', 'de', 'Kreuzheben mit der Trap Bar', 'Kreuzheben in der sechseckigen Trap Bar: Das Gewicht liegt seitlich am Körper, der Oberkörper bleibt aufrechter. Leichter zu lernen und schonender für den Rücken als klassisches Kreuzheben.'),
  ('trap-bar-deadlifts', 'en', 'Trap Bar Deadlifts', 'Deadlifts in the hexagonal trap bar: the weight sits at your sides and your upper body stays more upright. Easier to learn and gentler on the back than conventional deadlifts.'),
  ('underhand-barbell-rows', 'de', 'Langhantelrudern im Untergriff', 'Vorgebeugt die Langhantel im Untergriff zum Bauch ziehen. Der Untergriff hält die Ellbogen nah am Körper und verlagert die Arbeit stärker in den Latissimus.'),
  ('underhand-barbell-rows', 'en', 'Underhand Barbell Rows', 'Bent over, pull the barbell to your stomach with an underhand grip. The underhand grip keeps the elbows close to the body and shifts more of the work to the lats.'),
  ('wide-grip-barbell-curls', 'de', 'Langhantel-Curls mit weitem Griff', 'Curls mit Händen weiter als schulterbreit. Der weite Griff betont den kurzen Kopf.'),
  ('wide-grip-barbell-curls', 'en', 'Wide-Grip Barbell Curls', 'Curls with your hands wider than shoulder width. The wide grip emphasises the short head.'),
  ('wide-grip-cable-row', 'de', 'Kabelrudern mit breitem Griff', 'Im Sitzen die breite Stange zur unteren Brust ziehen, Ellbogen nach außen, und die Schulterblätter am Ende fest zusammendrücken.'),
  ('wide-grip-cable-row', 'en', 'Wide-Grip Cable Row', 'Seated, pull the wide bar to your lower chest with elbows out, and squeeze your shoulder blades hard at the end.'),
  ('wide-grip-upright-row', 'de', 'Aufrechtes Rudern mit breitem Griff', 'Die Stange mit breitem Griff am Körper entlang bis knapp unter die Brust ziehen, Ellbogen führen. Nicht höher ziehen, um die Schulter zu schonen.'),
  ('wide-grip-upright-row', 'en', 'Wide-Grip Upright Row', 'Pull the bar up along your body with a wide grip to just below your chest, leading with the elbows. Don''t pull higher, to protect your shoulders.'),
  ('wrist-curls', 'de', 'Handgelenk-Curls', 'Unterarme auf den Oberschenkeln, Handflächen nach oben. Das Gewicht bis in die Fingerspitzen rollen lassen und mit dem Handgelenk wieder hochcurlen.'),
  ('wrist-curls', 'en', 'Wrist Curls', 'Forearms on your thighs, palms up. Let the weight roll down to your fingertips and curl it back up with your wrist.'),
  ('wrist-roller', 'de', 'Wrist Roller', 'Mit ausgestreckten Armen ein Gewicht an einer Schnur auf- und wieder abrollen. Trainiert Beuger und Strecker des Unterarms gleichzeitig.'),
  ('wrist-roller', 'en', 'Wrist Roller', 'With outstretched arms, roll a weight on a cord up and back down. Trains the forearm flexors and extensors at the same time.');

