INSERT INTO exercise_tip (exercise_id, language, kind, position, text) VALUES
  ('ab-crunch-machine', 'de', 'cue', 1, 'Sitz so einstellen, dass die Polster auf Brust bzw. Schultern liegen.'),
  ('ab-crunch-machine', 'de', 'cue', 2, 'Den Oberkörper einrollen, nicht aus der Hüfte nach vorne kippen.'),
  ('ab-crunch-machine', 'de', 'cue', 3, 'Langsam zurück, ohne das Gewicht abzulegen.'),
  ('ab-crunch-machine', 'en', 'cue', 1, 'Set the seat so the pads rest on your chest or shoulders.'),
  ('ab-crunch-machine', 'en', 'cue', 2, 'Curl your upper body; don''t just tip forward from the hips.'),
  ('ab-crunch-machine', 'en', 'cue', 3, 'Return slowly without setting the weight down.'),
  ('ab-crunch-machine', 'de', 'mistake', 1, 'Mit den Armen ziehen.'),
  ('ab-crunch-machine', 'de', 'mistake', 2, 'Zu schweres Gewicht mit Schwung.'),
  ('ab-crunch-machine', 'de', 'mistake', 3, 'Nur aus der Hüfte beugen.'),
  ('ab-crunch-machine', 'en', 'mistake', 1, 'Pulling with the arms.'),
  ('ab-crunch-machine', 'en', 'mistake', 2, 'Too heavy, with momentum.'),
  ('ab-crunch-machine', 'en', 'mistake', 3, 'Only bending at the hips.'),
  ('ab-wheel-rollout', 'de', 'cue', 1, 'Aus den Knien starten, Bauch fest.'),
  ('ab-wheel-rollout', 'de', 'cue', 2, 'Nur so weit rollen, wie der Rücken gerade bleibt.'),
  ('ab-wheel-rollout', 'de', 'cue', 3, 'Mit dem Bauch zurückziehen.'),
  ('ab-wheel-rollout', 'en', 'cue', 1, 'Start from your knees, abs tight.'),
  ('ab-wheel-rollout', 'en', 'cue', 2, 'Only roll as far as your back stays straight.'),
  ('ab-wheel-rollout', 'en', 'cue', 3, 'Pull back with your abs.'),
  ('ab-wheel-rollout', 'de', 'mistake', 1, 'Hohlkreuz.'),
  ('ab-wheel-rollout', 'de', 'mistake', 2, 'Zu weit rollen.'),
  ('ab-wheel-rollout', 'de', 'mistake', 3, 'Mit den Armen statt dem Bauch zurückziehen.'),
  ('ab-wheel-rollout', 'en', 'mistake', 1, 'Arched lower back.'),
  ('ab-wheel-rollout', 'en', 'mistake', 2, 'Rolling too far.'),
  ('ab-wheel-rollout', 'en', 'mistake', 3, 'Pulling back with the arms instead of the abs.'),
  ('alternating-dumbbell-curls', 'de', 'cue', 1, 'Mit neutralem Griff starten und beim Hochcurlen nach außen drehen.'),
  ('alternating-dumbbell-curls', 'de', 'cue', 2, 'Ellbogen bleibt am Körper.'),
  ('alternating-dumbbell-curls', 'de', 'cue', 3, 'Langsam absenken, dann Seite wechseln.'),
  ('alternating-dumbbell-curls', 'en', 'cue', 1, 'Start with a neutral grip and rotate outward as you curl up.'),
  ('alternating-dumbbell-curls', 'en', 'cue', 2, 'Elbow stays at your side.'),
  ('alternating-dumbbell-curls', 'en', 'cue', 3, 'Lower slowly, then switch sides.'),
  ('alternating-dumbbell-curls', 'de', 'mistake', 1, 'Oberkörper dreht mit.'),
  ('alternating-dumbbell-curls', 'de', 'mistake', 2, 'Schwung aus der Schulter.'),
  ('alternating-dumbbell-curls', 'de', 'mistake', 3, 'Zu schnell wechseln.'),
  ('alternating-dumbbell-curls', 'en', 'mistake', 1, 'Upper body rotating along.'),
  ('alternating-dumbbell-curls', 'en', 'mistake', 2, 'Momentum from the shoulder.'),
  ('alternating-dumbbell-curls', 'en', 'mistake', 3, 'Switching too fast.'),
  ('arnold-press', 'de', 'cue', 1, 'Start: Hanteln vor dem Gesicht, Handflächen zum Körper.'),
  ('arnold-press', 'de', 'cue', 2, 'Beim Hochdrücken die Arme öffnen und die Hände nach außen drehen.'),
  ('arnold-press', 'de', 'cue', 3, 'Den Weg zurück genauso kontrolliert drehen.'),
  ('arnold-press', 'en', 'cue', 1, 'Start: dumbbells in front of your face, palms facing you.'),
  ('arnold-press', 'en', 'cue', 2, 'As you press, open your arms and rotate your hands outward.'),
  ('arnold-press', 'en', 'cue', 3, 'Rotate back down with the same control.'),
  ('arnold-press', 'de', 'mistake', 1, 'Erst drehen, dann drücken – beides soll gleichzeitig passieren.'),
  ('arnold-press', 'de', 'mistake', 2, 'Zu schwer, sodass die Drehung abgehackt wird.'),
  ('arnold-press', 'de', 'mistake', 3, 'Hohlkreuz im Stand – lieber sitzend mit Lehne.'),
  ('arnold-press', 'en', 'mistake', 1, 'Rotating first, then pressing – both should happen at the same time.'),
  ('arnold-press', 'en', 'mistake', 2, 'Too heavy, so the rotation gets choppy.'),
  ('arnold-press', 'en', 'mistake', 3, 'Arching the lower back when standing – better seated with back support.'),
  ('assisted-pull-ups', 'de', 'cue', 1, 'Knie auf das Polster, Hände etwas weiter als schulterbreit.'),
  ('assisted-pull-ups', 'de', 'cue', 2, 'Brust zur Stange ziehen, Ellbogen nach unten.'),
  ('assisted-pull-ups', 'de', 'cue', 3, 'Unten die Arme fast ganz strecken.'),
  ('assisted-pull-ups', 'en', 'cue', 1, 'Knees on the pad, hands slightly wider than shoulder width.'),
  ('assisted-pull-ups', 'en', 'cue', 2, 'Pull your chest to the bar, elbows down.'),
  ('assisted-pull-ups', 'en', 'cue', 3, 'Extend your arms almost fully at the bottom.'),
  ('assisted-pull-ups', 'de', 'mistake', 1, 'So viel Unterstützung, dass es kaum fordert.'),
  ('assisted-pull-ups', 'de', 'mistake', 2, 'Nur halbe Wiederholungen.'),
  ('assisted-pull-ups', 'de', 'mistake', 3, 'Mit Schwung aus den Beinen hochkommen.'),
  ('assisted-pull-ups', 'en', 'mistake', 1, 'So much assistance that it''s hardly challenging.'),
  ('assisted-pull-ups', 'en', 'mistake', 2, 'Only half reps.'),
  ('assisted-pull-ups', 'en', 'mistake', 3, 'Coming up with momentum from the legs.'),
  ('back-extensions', 'de', 'cue', 1, 'Polster knapp unter dem Hüftknochen.'),
  ('back-extensions', 'de', 'cue', 2, 'Mit geradem Rücken in der Hüfte beugen.'),
  ('back-extensions', 'de', 'cue', 3, 'Nur bis zur geraden Linie hochkommen.'),
  ('back-extensions', 'en', 'cue', 1, 'Pad just below your hip bones.'),
  ('back-extensions', 'en', 'cue', 2, 'Hinge at the hips with a straight back.'),
  ('back-extensions', 'en', 'cue', 3, 'Only come up to a straight line.'),
  ('back-extensions', 'de', 'mistake', 1, 'Oben stark ins Hohlkreuz überstrecken.'),
  ('back-extensions', 'de', 'mistake', 2, 'Ruckartig aus dem Schwung hochkommen.'),
  ('back-extensions', 'de', 'mistake', 3, 'Polster zu hoch – dann ist kaum Bewegung möglich.'),
  ('back-extensions', 'en', 'mistake', 1, 'Overarching the lower back at the top.'),
  ('back-extensions', 'en', 'mistake', 2, 'Jerking up with momentum.'),
  ('back-extensions', 'en', 'mistake', 3, 'Pad too high – then there is hardly any movement.'),
  ('banded-lateral-walks', 'de', 'cue', 1, 'Band um Knie oder Knöchel, leichte Kniebeuge.'),
  ('banded-lateral-walks', 'de', 'cue', 2, 'Seitwärts gehen, Spannung im Band halten.'),
  ('banded-lateral-walks', 'de', 'cue', 3, 'Füße zeigen nach vorn.'),
  ('banded-lateral-walks', 'en', 'cue', 1, 'Band around your knees or ankles, slight squat.'),
  ('banded-lateral-walks', 'en', 'cue', 2, 'Walk sideways, keeping tension in the band.'),
  ('banded-lateral-walks', 'en', 'cue', 3, 'Feet point forward.'),
  ('banded-lateral-walks', 'de', 'mistake', 1, 'Aufrichten aus der Kniebeuge.'),
  ('banded-lateral-walks', 'de', 'mistake', 2, 'Knie fallen nach innen.'),
  ('banded-lateral-walks', 'de', 'mistake', 3, 'Füße zu dicht zusammen – Band entspannt.'),
  ('banded-lateral-walks', 'en', 'mistake', 1, 'Standing up out of the squat.'),
  ('banded-lateral-walks', 'en', 'mistake', 2, 'Knees caving in.'),
  ('banded-lateral-walks', 'en', 'mistake', 3, 'Feet too close together – the band goes slack.'),
  ('barbell-back-squats', 'de', 'cue', 1, 'Stange auf dem oberen Rücken, Füße schulterbreit.'),
  ('barbell-back-squats', 'de', 'cue', 2, 'Knie folgen den Zehen nach außen.'),
  ('barbell-back-squats', 'de', 'cue', 3, 'Mindestens bis zur Parallelen, Brust bleibt oben.'),
  ('barbell-back-squats', 'en', 'cue', 1, 'Bar on your upper back, feet shoulder-width apart.'),
  ('barbell-back-squats', 'en', 'cue', 2, 'Knees track out over your toes.'),
  ('barbell-back-squats', 'en', 'cue', 3, 'At least to parallel; your chest stays up.'),
  ('barbell-back-squats', 'de', 'mistake', 1, 'Knie fallen nach innen.'),
  ('barbell-back-squats', 'de', 'mistake', 2, 'Fersen heben ab.'),
  ('barbell-back-squats', 'de', 'mistake', 3, 'Runder Rücken unten („Butt Wink“).'),
  ('barbell-back-squats', 'en', 'mistake', 1, 'Knees caving in.'),
  ('barbell-back-squats', 'en', 'mistake', 2, 'Heels lifting off.'),
  ('barbell-back-squats', 'en', 'mistake', 3, 'Rounding the back at the bottom ("butt wink").'),
  ('barbell-bench-press', 'de', 'cue', 1, 'Füße fest am Boden, Schulterblätter zusammen und nach unten.'),
  ('barbell-bench-press', 'de', 'cue', 2, 'Stange zur unteren bis mittleren Brust absenken, Unterarme senkrecht.'),
